int is_palindrome(char s[]) {
    int len = 0;
    int i;
    int ans = 1;
    int temp1;
    // yaha length add karo
    while (s[len] != '\0') {
        len++;
    }
    temp1 = len - 1;
    for (i = 0; i < len / 2; i++) {
        if (s[i] != s[temp1 - i]) {
            ans = 0;
            break;
        }
    }
    // printf("debug len=%d temp1=%d ans=%d", len, temp1, ans); // leftover debug
    return ans;
}
